import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import './Inscripcion.css';

const Inscripcion = ({ cursoId }) => {
  const navigate = useNavigate();

  // Estado para el formulario
  const [formData, setFormData] = useState({
    nombre: '',
    email: '',
    telefono: '',
    edad: '',
  });

  // Estado para controlar si la inscripción fue exitosa
  const [isInscribed, setIsInscribed] = useState(false);

  // Estado para almacenar preguntas y opciones
  const [preguntas, setPreguntas] = useState([]);

  // Obtener preguntas desde el backend
  useEffect(() => {
    fetch('http://localhost:3001/api/preguntas')
      .then((response) => response.json())
      .then((data) => setPreguntas(data.preguntas))
      .catch((error) => console.error('Error al obtener preguntas:', error));
  }, []);

  // Manejar los cambios en los campos del formulario
  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prevData) => ({
      ...prevData,
      [name]: value,
    }));
  };

  // Enviar los datos al backend para crear la inscripción
  const handleSubmit = async (e) => {
    e.preventDefault();

    const response = await fetch('http://localhost:3001/api/usuarios/inscribirse', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        ...formData,
        cursoId: cursoId, // Enviar el ID del curso seleccionado
      }),
    });

    if (response.ok) {
      setIsInscribed(true);
      setTimeout(() => {
        navigate(`/pago/${cursoId}`); // Redirigir a la página de pago
      }, 2000);
    } else {
      alert('Error al inscribirse');
    }
  };

  return (
    <div className="inscripcion">
      {!isInscribed ? (
        <>
          <h2>Inscribirse al Curso</h2>
          <form onSubmit={handleSubmit}>
            <input
              type="text"
              name="nombre"
              placeholder="Nombre"
              value={formData.nombre}
              onChange={handleChange}
            />
            <input
              type="email"
              name="email"
              placeholder="Email"
              value={formData.email}
              onChange={handleChange}
            />
            <input
              type="text"
              name="telefono"
              placeholder="Teléfono"
              value={formData.telefono}
              onChange={handleChange}
            />
            <input
              type="number"
              name="edad"
              placeholder="Edad"
              value={formData.edad}
              onChange={handleChange}
            />

            {/* Mostrar preguntas dinámicamente */}
            {preguntas.length > 0 && (
              <div>
                <h3>Preguntas</h3>
                {preguntas.map((pregunta) => (
                  <div key={pregunta.id}>
                    <p><strong>{pregunta.texto}</strong></p>
                    {pregunta.Opciones?.map((opcion) => (
                      <label key={opcion.id}>
                        <input type="radio" name={`pregunta_${pregunta.id}`} value={opcion.id} />
                        {opcion.texto}
                      </label>
                    ))}
                  </div>
                ))}
              </div>
            )}

            <button type="submit">Inscribirse</button>
          </form>
        </>
      ) : (
        <div className="inscripcion-exitosa">
          <h3>¡Inscripción exitosa!</h3>
        </div>
      )}
    </div>
  );
};

export default Inscripcion;
